// One Workspace settings component supplies presentation defaults and startup configuration.
// Execution mode and initial sketch are authoring settings, never live control inputs.
({
  apiVersion:2,
  settings:{executionMode:{type:'string',default:'active sketch',options:['active sketch','whole workspace'],label:'Execution mode'}},
  workspaceSettings:{title:'title',showTabs:'showTabs',showWiring:'showWiring',showSimulationControls:'showSimulationControls'},
  initState(){return {executionMode:'active sketch',initialSketchId:'',tabVisibility:[]};},
  initStyle(){return {w:330,h:184,fontSize:18,fill:true,fillColor:'#f8fafc',strokeOn:true,color:'#94a3b8',textColor:'#334155',size:1.5};},
  _configuration(state){
    if(!['active sketch','whole workspace'].includes(state.executionMode))throw new Error('Choose Active sketch only or Whole workspace');
    if(typeof state.initialSketchId!=='string' || state.initialSketchId.length>100)throw new Error('Initial sketch must be a sketch ID of at most 100 characters');
    const entries=state.tabVisibility;
    if(!Array.isArray(entries) || entries.length>128)throw new Error('Tab visibility supports at most 128 sketches');
    const ids=new Set(),ports=new Set();
    for(const entry of entries){
      if(!entry || typeof entry!=='object' || Array.isArray(entry) || Object.keys(entry).some(key=>!['sketchId','visible','input'].includes(key)) ||
        typeof entry.sketchId!=='string' || !entry.sketchId || entry.sketchId.length>100 || ids.has(entry.sketchId) || typeof entry.visible!=='boolean' ||
        entry.input!==undefined && (typeof entry.input!=='string' || entry.input!=='' && !/^tab[A-Za-z0-9_]{1,27}$/.test(entry.input)))throw new Error('Each tab visibility entry needs a unique sketch ID, Boolean visibility and optional control input');
      ids.add(entry.sketchId);
      if(entry.input){if(ports.has(entry.input))throw new Error('Tab visibility control inputs must be unique');ports.add(entry.input);}
    }
    if(ports.size>28)throw new Error('At most 28 sketch tabs can have live visibility inputs');
    return entries;
  },
  inputs(state){
    const ports={title:{type:'string',default:'',label:'Default window title'},
      showTabs:{role:'control',type:'boolean',default:true,label:'Show tab bar'},
      showWiring:{role:'control',type:'boolean',default:false,label:'Show wiring'},
      showSimulationControls:{role:'control',type:'boolean',default:true,label:'Show simulation controls'}};
    for(const entry of this._configuration(state))if(entry.input)ports[entry.input]={role:'control',type:'boolean',default:entry.visible,label:'Show sketch tab'};
    return ports;
  },
  outputs:{},
  compute(inputs,state){
    const ports=this.inputs(state);
    if(typeof inputs.title!=='string' || inputs.title.length>2000)throw new Error('Window title must be text of at most 2000 characters');
    for(const [key,port] of Object.entries(ports))if(port.type==='boolean' && typeof inputs[key]!=='boolean')throw new Error(port.label+' must be Boolean');
    return {};
  },
  _text(value,x,y,w,h,size,style,color=style.textColor||'#334155',weight=400){
    const content=String(value).replace(/\s+/g,' '),chars=typeof Intl!=='undefined' && typeof Intl.Segmenter==='function'?Array.from(new Intl.Segmenter(undefined,{granularity:'grapheme'}).segment(content),part=>part.segment):content?[content]:[];
    const units=char=>/[MWmw@#%]/.test(char)||char.codePointAt(0)>255?1.1:/[A-Z]/.test(char)?.88:.72;
    let text='',used=0;
    for(let i=0;i<chars.length;i++){
      const next=units(chars[i]),remaining=i<chars.length-1?1.1:0;
      if((used+next+remaining)*size>w){text+='…';break;}
      text+=chars[i];used+=next;
    }
    const font=(style.font||weight+' '+size+'px sans-serif').replace(/\d+(?:\.\d+)?px/,size+'px');
    return {type:'text',x,y,w,h,text,plainText:true,align:'left',font,color,strokeOn:false,editorOnly:true};
  },
  children(state,style,w,h,editing,io={}){
    const scale=Math.min(w/330,h/184),pad=12*scale,name=(typeof io.name==='string'?io.name:'').trim()||'Workspace settings';
    const text=(value,y,size=11,color=style.textColor||'#334155',weight=400)=>this._text(value,pad,y*scale,w-pad*2,18*scale,size*scale,style,color,weight);
    const children=[{type:'rect',x:0,y:0,w,h,fill:style.fill!==false,fillColor:style.fillColor||'#f8fafc',strokeOn:style.strokeOn!==false,color:style.color||'#94a3b8',size:style.size,dash:style.dash,editorOnly:true},text(name,12,13,style.textColor||'#334155',600)];
    if(io.error)children.push(text(io.error,44,11,'#92400e'),text('Application defaults apply',68,11,'#64748b'));
    else{
      const inputs={title:'',showTabs:true,showWiring:false,showSimulationControls:true,...io.inputs};
      children.push(text('Title: '+(inputs.title||'Workspace name'),42,12),text('Tab bar: '+(inputs.showTabs?'shown':'hidden')+' · Wiring: '+(inputs.showWiring?'shown':'hidden'),66),
        text('Simulation controls: '+(inputs.showSimulationControls?'shown':'hidden'),88),text(state.executionMode==='whole workspace'?'Execution: Whole workspace':'Execution: Active sketch only',110));
    }
    children.push(text('Defaults apply across all sketches',138,10,'#64748b'),text('Authoring only · one per workspace',158,10,'#64748b'));
    return children;
  },
  unavailableChildren(state,style,w,h,editing,io={}){return this.children(state,style,w,h,editing,{...io,error:io.error||'Input unavailable'});}
})

// Wall-clock readings and nominal 100 ms boundary pulses in a selected timezone.
// Reopening, changing timezone, and missed/adjusted clock time re-prime without replaying ticks.
// The host schedules transitions; compute and image exports use the last settled snapshot.
({
  apiVersion:2,
  wakePolicy:'latest',
  inputs:{timezone:{role:'control',type:'string',default:'local'}},
  outputs:{second:{role:'control',type:'boolean'},minute:{role:'control',type:'boolean'},hour:{role:'control',type:'boolean'},halfDay:{role:'control',type:'boolean'},time:{type:'string'}},
  initState(){return {time:'00:00:00',second:false,minute:false,hour:false,halfDay:false,showIndicators:true};},
  initStyle(){return {w:220,h:300,strokeOn:false,fontSize:16};},
  _formatter(timezone){
    if(typeof timezone!=='string' || !timezone.trim() || timezone.length>128)throw new Error('Timezone must be local or a valid timezone name, such as Europe/Berlin');
    const zone=timezone.trim();
    try{return new Intl.DateTimeFormat('en-GB',{...(zone.toLowerCase()==='local'?{}:{timeZone:zone}),
      hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23',numberingSystem:'latn'});}
    catch(_){throw new Error('Invalid timezone: use local, UTC, or a timezone name such as Europe/Berlin');}
  },
  _validate(state){
    if(typeof state.time!=='string' || !/^(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d$/.test(state.time) ||
       ['second','minute','hour','halfDay'].some(key=>typeof state[key]!=='boolean') || typeof state.showIndicators!=='boolean')throw new Error('Invalid Live clock state');
  },
  transition(inputs,state,memory,context){
    const {now}=context;
    this._validate(state);
    if(!Number.isFinite(now) || now<0)throw new Error('Live clock requires a valid monotonic time');
    const formatter=this._formatter(inputs.timezone),wall=Date.now();
    if(!Number.isFinite(wall) || Math.abs(wall)>8640000000000000)throw new Error('Live clock requires a valid wall-clock time');
    const parts=Object.fromEntries(formatter.formatToParts(new Date(wall)).map(part=>[part.type,part.value]));
    const hour=Number(parts.hour)%24,minute=Number(parts.minute),second=Number(parts.second);
    const time=[hour,minute,second].map(value=>String(value).padStart(2,'0')).join(':');
    const zone=formatter.resolvedOptions().timeZone,epochSecond=Math.floor(wall/1000);
    const fresh=memory==null || (typeof memory==='object' && !Array.isArray(memory) && Object.keys(memory).length===0);
    if(!fresh && (typeof memory.zone!=='string' || !Number.isFinite(memory.wall) || !Number.isSafeInteger(memory.epochSecond) ||
       memory.epochSecond!==Math.floor(memory.wall/1000) || !Number.isFinite(memory.now) || memory.now<0 ||
       (memory.until!==null && (!Number.isFinite(memory.until) || memory.until<=memory.now))))throw new Error('Invalid Live clock scheduling memory');
    // Replaying an earlier queued signal must not consume this wall-clock wake.
    if(context.historical && !fresh && memory.zone===zone){
      const nextWakeAt=memory.until===null?memory.now+1000-((memory.wall%1000+1000)%1000):memory.until;
      return {state,memory,nextWakeAt};
    }
    // Active-document time pauses while hidden. A wall/active-time discontinuity resets observation,
    // as does a backwards clock adjustment. Small scheduling jitter does not erase a normal tick.
    const restart=fresh || memory.zone!==zone || wall<memory.wall || now<memory.now ||
      Math.abs((wall-memory.wall)-(now-memory.now))>500;
    let secondTick=false,minuteTick=false,hourTick=false,halfDayTick=false,until=null;
    if(!restart){
      if(memory.until!==null){
        // An overdue high must fall before another rise; never turn missed ticks into a burst.
        if(now<memory.until){
          secondTick=state.second;minuteTick=state.minute;hourTick=state.hour;halfDayTick=state.halfDay;until=memory.until;
        }
      }else if(epochSecond===memory.epochSecond+1){
        secondTick=true;minuteTick=second===0;hourTick=minuteTick && minute===0;halfDayTick=hourTick && hour%12===0;
        until=now+100;
      }
    }
    const nextWakeAt=until===null?now+1000-((wall%1000+1000)%1000):until;
    if(!Number.isFinite(nextWakeAt) || nextWakeAt<=now)throw new Error('Live clock wake time is outside the numeric range');
    return {state:{...state,time,second:secondTick,minute:minuteTick,hour:hourTick,halfDay:halfDayTick},
      memory:{zone,wall,now,epochSecond,until},nextWakeAt};
  },
  publish(state){
    this._validate(state);
    return {second:state.second,minute:state.minute,hour:state.hour,halfDay:state.halfDay,time:state.time};
  },
  compute(inputs,state){
    this._formatter(inputs.timezone);this._validate(state);
    return {second:state.second,minute:state.minute,hour:state.hour,halfDay:state.halfDay,time:state.time};
  },
  _caption(name,fallback,w,h,style){
    const label=(typeof name==='string'?name:'').trim().replace(/\s+/g,' ')||fallback;
    const units=text=>Array.from(text).reduce((n,c)=>n+(/[MWmw@#%]/.test(c)||c.codePointAt(0)>255?1.1:/[A-Z]/.test(c)?.88:.72),0);
    const width=Math.max(1,w-16),base=Math.min(style.fontSize||20,h*.7);
    let size=Math.min(base,width/Math.max(1,units(label))),lines=[label];
    if(size<Math.min(12,base)){
      size=Math.min(base,12,Math.max(1,h-2)/2.4,width/1.1);lines=[];let rest=label;
      for(let row=0;row<2 && rest;row++){
        let line='';for(const c of rest){if(line && units(line+c)*size>width)break;line+=c;}
        if(line.length<rest.length && line.lastIndexOf(' ')>0)line=line.slice(0,line.lastIndexOf(' '));
        rest=rest.slice(line.length).trim();
        if(row===1 && rest){while(line && units(line+'…')*size>width)line=Array.from(line).slice(0,-1).join('');line+='…';}
        lines.push(line);
      }
    }
    return {text:lines.join('\n'),font:(style.font||'600 20px sans-serif').replace(/\d+(?:\.\d+)?px/,size+'px')};
  },
  children(state,style,w,h,editing,io={}){
    const available=!io.error && /^(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d$/.test(io.outputs?.time);
    const scale=Math.min(w/220,h/300),top=24*scale,d=Math.max(1,Math.min(w-16*scale,h-112*scale));
    const cx=w/2,cy=top+d/2,r=d/2,thin=Math.max(1,(style.size||2)/2);
    const text=(value,x,y,width,height,size)=>({type:'text',x,y,w:width,h:height,text:value,align:'center',
      font:'600 '+Math.max(6,size*scale)+'px sans-serif',color:style.textColor||style.color,textColor:style.textColor||style.color,strokeOn:false,fill:false});
    const items=[{...text('',0,0,w,22*scale,16),...this._caption(io.name,'Live clock',w,22*scale,{...style,fontSize:16*scale})},
      {type:'ellipse',x:cx-r,y:top,w:d,h:d,color:style.color,size:thin,strokeOn:true,fill:style.fill,fillColor:style.fillColor}];
    for(let i=0;i<12;i++){
      const angle=i/12*Math.PI*2;
      items.push({type:'line',x1:cx+Math.sin(angle)*r*.84,y1:cy-Math.cos(angle)*r*.84,
        x2:cx+Math.sin(angle)*r*.95,y2:cy-Math.cos(angle)*r*.95,color:style.color,size:thin});
    }
    if(available){
      const [hour,minute,second]=io.outputs.time.split(':').map(Number),minutes=minute+second/60,hours=hour%12+minutes/60;
      for(const [value,total,length,size,color] of [[hours,12,.5,style.size||2,style.color],
        [minutes,60,.72,style.size||2,style.color],[second,60,.82,thin,style.textColor||style.color]]){
        const angle=value/total*Math.PI*2;
        items.push({type:'line',x1:cx,y1:cy,x2:cx+Math.sin(angle)*r*length,y2:cy-Math.cos(angle)*r*length,color,size});
      }
    }
    const timezone=typeof io.inputs?.timezone==='string'?io.inputs.timezone.trim():'local';
    const zoneLabel=available?(timezone.toLowerCase()==='local'?'Local time':timezone):/timezone/i.test(io.error||'')?'Invalid timezone':'Clock unavailable';
    items.push(text(available?io.outputs.time:'--:--:--',0,top+d+6*scale,w,22*scale,20),
      {...text('',0,top+d+31*scale,w,16*scale,11),...this._caption(zoneLabel,'Local time',w,16*scale,{...style,fontSize:11*scale}),
        ...(!available?{color:'#92400e',textColor:'#92400e'}:{})});
    if(state.showIndicators!==false){
      for(const [index,[key,label]] of [['second','1 s'],['minute','1 m'],['hour','1 h'],['halfDay','12 h']].entries()){
        const x=w*(index+.5)/4,y=h-28*scale,radius=3*scale;
        items.push({type:'ellipse',x:x-17*scale-radius,y:y-radius,w:radius*2,h:radius*2,fill:true,
          fillColor:available?(io.outputs[key]?'#15803d':'#94a3b8'):'#fbbf24',strokeOn:false},
          text(label,x-11*scale,y-8*scale,35*scale,16*scale,9));
      }
    }
    if(editing && available){
      items.push({type:'rect',x:0,y:h-17*scale,w,h:17*scale,fill:true,fillColor:'#e2e8f0',strokeOn:false,editorOnly:true},
        {...text('Indicators: '+(state.showIndicators?'on':'off'),0,h-17*scale,w,17*scale,10),editorOnly:true});
    }
    return items;
  },
  unavailableChildren(state,style,w,h,editing,io={}){return this.children(state,style,w,h,false,{...io,outputs:{}});},
  handles(state,w,h){return [{id:'indicators',x:w/2,y:h-8.5*Math.min(w/220,h/300),kind:'click',editorOnly:true}];},
  hitEdit(state,x,y,w,h){return x>=0 && x<=w && y>=h-17*Math.min(w/220,h/300) && y<=h?'indicators':null;},
  dragEdit(state,handle){return {state:handle==='indicators'?{...state,showIndicators:!state.showIndicators}:state};}
})

// Publish several named, typed endpoints from this sketch.
// Stable endpoint IDs preserve connections when labels or row order change.
({
  apiVersion:2,
  eventApi:1,
  settings:{},
  initState(){return {endpoints:[{id:'value',name:'Value',type:'string',description:''}]};},
  initStyle(){return {w:320,h:100,fontSize:18,fill:true,fillColor:'#eef2ff',strokeOn:true,color:'#818cf8',textColor:'#3730a3',size:1.5};},
  _rows(state){
    if(!state || !Array.isArray(state.endpoints) || state.endpoints.length<1 || state.endpoints.length>16)throw new Error('Configure 1–16 endpoints');
    const ids=new Set();
    for(const row of state.endpoints){
      if(!row || typeof row!=='object' || Array.isArray(row) || Object.keys(row).some(key=>!['id','name','type','description'].includes(key)) ||
        typeof row.id!=='string' || !/^[A-Za-z][A-Za-z0-9_]{0,47}$/.test(row.id) || ['constructor','prototype','__proto__'].includes(row.id) || ids.has(row.id))throw new Error('Endpoint IDs must be unique stable identifiers');
      if(typeof row.name!=='string' || !row.name.trim() || row.name.length>64)throw new Error('Endpoint name must contain 1–64 characters');
      if(!['string','number','boolean','table','event'].includes(row.type))throw new Error('Choose a text, number, Boolean, table, or event endpoint');
      if(typeof row.description!=='string' || row.description.length>200)throw new Error('Endpoint description must be text of at most 200 characters');
      ids.add(row.id);
    }
    return state.endpoints;
  },
  _value(value,row){
    if(row.type==='table'){
      if(!value || typeof value!=='object' || Array.isArray(value) || typeof value.datasetId!=='string')throw new Error(row.name+' requires a table input');
    }else if(typeof value!==row.type || row.type==='number' && !Number.isFinite(value) || row.type==='string' && value.length>2000)throw new Error(row.name+' must match its declared type');
    return value;
  },
  _event(payload,row){
    if(payload!==null && !['boolean','number','string'].includes(typeof payload) || typeof payload==='number' && !Number.isFinite(payload) || typeof payload==='string' && payload.length>2000)throw new Error('Unsupported event payload');
    if(row.type!=='event' && typeof payload!==row.type)throw new Error('Event payload must match its declared type');
  },
  _text(value,x,y,w,h,size,color,weight=400){
    const content=String(value).replace(/\s+/g,' '),chars=typeof Intl!=='undefined' && typeof Intl.Segmenter==='function'?Array.from(new Intl.Segmenter(undefined,{granularity:'grapheme'}).segment(content),part=>part.segment):Array.from(content);
    const limit=Math.max(1,Math.floor(w/(size*.7))),text=chars.length>limit?chars.slice(0,Math.max(0,limit-1)).join('')+'…':content;
    return {type:'text',x,y,w,h,text,plainText:true,align:'left',font:weight+' '+size+'px sans-serif',color,strokeOn:false};
  },
  workspaceEndpoint(state){return {direction:'publish',ports:Object.fromEntries(this._rows(state).map(row=>[row.id,{type:row.type}]))};},
  outputs(state){return Object.fromEntries(this._rows(state).filter(row=>row.type!=='event').map(row=>[row.id,{type:row.type,label:row.name,...(row.type==='table'?{}:{event:true})}]));},
  eventOutputs(state){return Object.fromEntries(this._rows(state).filter(row=>row.type==='event').map(row=>[row.id,{types:['none','boolean','number','string'],label:row.name,side:'right'}]));},
  inputs(state){return Object.fromEntries(this._rows(state).filter(row=>row.type!=='event').map(row=>[row.id,{type:row.type,label:row.name,...(row.type==='table'?{}:{event:true,default:row.type==='string'?'':row.type==='number'?0:false})}]));},
  eventInputs(state){return Object.fromEntries(this._rows(state).filter(row=>row.type==='event').map(row=>[row.id,{types:['none','boolean','number','string'],label:row.name,side:'left'}]));},
  compute(inputs,state){return Object.fromEntries(this._rows(state).filter(row=>row.type!=='event').map(row=>[row.id,this._value(inputs[row.id],row)]));},
  onEvent(name,payload,state){
    const row=this._rows(state).find(row=>row.id===name);if(!row)throw new Error('Unknown published event input');
    this._event(payload,row);return {state,events:[{port:row.id,payload}]};
  },
  children(state,style,w,h,editing,io={}){
    const rows=this._rows(state),baseH=64+rows.length*36,scale=Math.min(w/320,h/baseH),pad=12*scale,color=style.textColor||'#3730a3';
    const children=[{type:'rect',x:0,y:0,w,h,fill:style.fill!==false,fillColor:style.fillColor||'#eef2ff',strokeOn:style.strokeOn!==false,color:style.color||'#818cf8',size:style.size,dash:style.dash},
      this._text((typeof io.name==='string'?io.name:'').trim()||'Publish',pad,10*scale,w-pad*2,20*scale,13*scale,color,600)];
    rows.forEach((row,index)=>{
      const y=(36+index*36)*scale,type=row.type==='string'?'text':row.type==='event'?'events':row.type;
      children.push(this._text(row.name+' · '+type,pad,y,w-pad*2,18*scale,12*scale,color,600));
      const detail=row.description||'→ Workspace';
      children.push(this._text(detail,pad,y+18*scale,w-pad*2,14*scale,9*scale,'#64748b'));
    });
    if(io.error)children.push(this._text(io.error,pad,h-19*scale,w-pad*2,15*scale,9*scale,'#92400e'));
    return children;
  },
  unavailableChildren(state,style,w,h,editing,io={}){return this.children(state,style,w,h,editing,{...io,error:io.error||'Input unavailable'});}
})

// Own one stored dataset. Commands, source pulses or Live source publications copy incoming rows.
({
  apiVersion:2,
  eventApi:1,
  eventOutputs:{loaded:{type:'number'},replaced:{type:'number'},appended:{type:'number'},failed:{type:'string'}},
  actionEvents:{
    importDataset:{success:'loaded',failure:'failed'},
    reloadDataset:{success:'loaded',failure:'failed'},
    replaceTable:{success:'replaced',failure:'failed'},
    appendTable:{success:'appended',failure:'failed'},
    syncTable:{success:'replaced',failure:'failed'}
  },
  datasetOwner:'data',
  settings:{updateMode:{type:'string',default:'Manual',options:['Manual','Live'],label:'Source update mode'},allowReaderImport:{type:'boolean',default:false,label:'Allow file import and reload'},allowReaderColumnChanges:{type:'boolean',default:false,label:'Allow column changes in HTML export'},allowReaderUpdates:{type:'boolean',default:false,label:'Allow source updates in HTML export'}},
  inputs:{data:{type:'table'},source:{type:'table',optional:true},replace:{role:'control',type:'boolean',default:false,event:'action'},append:{role:'control',type:'boolean',default:false,event:'action'},reload:{role:'control',type:'boolean',default:false,event:'action'}},
  dataActions(state){return {reload:{type:'reloadDataset',input:'data',trigger:'reload'},replace:{type:'replaceTable',input:'data',source:'source',trigger:'replace'},append:{type:'appendTable',input:'data',source:'source',trigger:'append'},live:{type:'syncTable',input:'data',source:'source',enabled:state.updateMode==='Live'}};},
  outputs:{data:{type:'table'},rowCount:{type:'number'}},
  initState(){return {updateMode:'Manual',allowReaderImport:false,allowReaderColumnChanges:false,allowReaderUpdates:false};},
  initStyle(){return {w:300,h:150,fontSize:16,fill:true,fillColor:'#ffffff',strokeOn:true,color:'#94a3b8',textColor:'#334155',size:1};},
  compute(inputs,state,context={}){
    const table=context.tables?.data;
    if(!inputs.data || typeof inputs.data.datasetId!=='string' || !/^[A-Za-z0-9_-]{1,100}$/.test(inputs.data.datasetId) || Object.hasOwn(inputs.data,'rows') || !table || !Number.isInteger(table.rowCount) || table.rowCount<0)throw new Error('Choose an owned dataset in Edit');
    return {data:inputs.data,rowCount:table.rowCount};
  },
  _text(value,x,y,w,h,size,style,color=style.textColor||'#334155',weight=400){
    const units=char=>/[MWmw@#%]/.test(char)||char.codePointAt(0)>255?1.1:/[A-Z]/.test(char)?.88:.72;
    const chars=Array.from(String(value).replace(/\s+/g,' '));let text='',used=0;
    for(let i=0;i<chars.length;i++){
      const next=units(chars[i]),remaining=i<chars.length-1?1.1:0;
      if((used+next+remaining)*size>w){text+='…';break;}
      text+=chars[i];used+=next;
    }
    return {type:'text',x,y,w,h,text,plainText:true,align:'left',font:weight+' '+size+'px sans-serif',color,strokeOn:false};
  },
  children(state,style,w,h,editing,io={}){
    const scale=Math.min(w/300,h/150),pad=12*scale,table=io.tables?.inputs?.data;
